sys_script.script:
(function executeRule(current, previous) {

    // Run only when Onboarded changes to Yes.
    var newOnboarded = (current.getValue('onboarded') || '')
        .toLowerCase();
    var oldOnboarded = previous ?
        (previous.getValue('onboarded') || '').toLowerCase() :
        '';

    if (newOnboarded != 'yes' || oldOnboarded == 'yes') {
        return;
    }

    var supplierId = current.getUniqueValue();
    var isIndianSupplier = false;

    // 1. Check Country of Registration (String field).
    var registrationCountry =
        (current.getValue('registration_country') || '')
        .trim().toLowerCase();

    if (registrationCountry == 'india') {
        isIndianSupplier = true;
    }

    // 2. Check the supplier's shipping location.
    // cmn_location.country is a String choice field.
    if (!isIndianSupplier &&
        current.getValue('goods_shipped_from') != '') {

        var location = current.goods_shipped_from.getRefRecord();

        if (location && location.isValidRecord()) {
            var locationCountry =
                (location.getValue('country') || '')
                .trim().toLowerCase();

            if (locationCountry == 'india') {
                isIndianSupplier = true;
            }
        }
    }

    // 3. Check linked supplier payment records.
    // country references core_country.
    if (!isIndianSupplier) {
        var payment = new GlideRecord('sn_fin_supplier_payment');
        payment.addQuery('supplier', supplierId);
        payment.addQuery('country.name', 'India');
        payment.setLimit(1);
        payment.query();

        if (payment.next()) {
            isIndianSupplier = true;
        }
    }

    // Non-Indian suppliers are unaffected.
    if (!isIndianSupplier) {
        return;
    }

    // 4. Check for a verified profile or approved override.
    var hasVerifiedProfile = false;
    var hasApprovedOverride = false;

    var profile = new GlideRecord(
        'x_2078844_gstin_0_gst_compliance_profile'
    );
    profile.addQuery('supplier', supplierId);
    profile.query();

    while (profile.next()) {
        if (profile.getValue('result') == 'verified') {
            hasVerifiedProfile = true;
        }
        var ov = profile.getValue('override_approved');
        if (ov == '1' || ov == 'true') {
            hasApprovedOverride = true;
        }
    }

    // Allow activation only if verified or approved override exists.
    if (hasVerifiedProfile || hasApprovedOverride) {
        return;
    }

    gs.addErrorMessage(
        'This supplier is registered in India. Activation needs a verified GSTIN or an approved override.'
    );

    // setAbortAction is blocked cross-scope (sn_fin_supplier is in Finance Common Architecture),    // so revert the field instead: the supplier stays not onboarded.

    current.setValue('onboarded', previous.getValue('onboarded'));
    current.setValue('onboarded_date', previous.getValue('onboarded_date'));
    current.setValue('onboarded_by', previous.getValue('onboarded_by'));

})(current, previous);
